shaders.glsl:
// Bulb Reliquary — a raymarched Mandelbulb (Mandelbulber "mandelbulb") whose
// power breathes between 7 and 9, lit only by its own orbit-trap colour.
#define TAU 6.28318530718

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Closest approach per axis, plus closest approach to the origin in w.
void orbitTrap(vec3 z, inout vec4 trap){
    trap = min(trap, vec4(abs(z), dot(z, z)));
}

// Hubbard-Douady potential: DE = 0.5 * log(r) * r / dr.
// esc returns how far through the iteration the point survived, 0..1 — the
// escape banding is what carries the colour.
float deMandelbulb(vec3 pos, float power, inout vec4 trap, out float esc){
    vec3 z = pos;
    float dr = 1.0;
    float r = length(z);
    esc = 1.0;
    for (int i = 0; i < 8; i++){
        r = length(z);
        if (r > 2.0){ esc = float(i) / 8.0; break; }
        orbitTrap(z, trap);
        dr = pow(r, power - 1.0) * power * dr + 1.0;
        float theta = acos(clamp(z.z / r, -1.0, 1.0));
        float phi = atan(z.y, z.x);
        float zr = pow(r, power);
        theta *= power;
        phi *= power;
        z = zr * vec3(sin(theta) * cos(phi), sin(theta) * sin(phi), cos(theta)) + pos;
    }
    // Guards log(0) at the exact origin, which would return NaN and stall the march.
    return 0.5 * log(max(r, 1e-6)) * r / dr;
}

vec3 calcNormal(vec3 p, float power, float eps){
    vec2 k = vec2(1.0, -1.0);
    vec4 t = vec4(1e6);
    float e;
    return normalize(
        k.xyy * deMandelbulb(p + k.xyy * eps, power, t, e) +
        k.yyx * deMandelbulb(p + k.yyx * eps, power, t, e) +
        k.yxy * deMandelbulb(p + k.yxy * eps, power, t, e) +
        k.xxx * deMandelbulb(p + k.xxx * eps, power, t, e));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;
    float power = 8.0 + 1.1 * sin(t * 0.23);

    // Orbit the bulb, drifting above and below its equator.
    float a = t * 0.16;
    vec3 eye = vec3(cos(a) * 2.35, 0.62 * sin(t * 0.19), sin(a) * 2.35);
    vec3 fwd = normalize(-eye);
    vec3 rgt = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
    vec3 up  = cross(rgt, fwd);
    vec3 rd  = normalize(uv.x * rgt + uv.y * up + 1.7 * fwd);

    float dist = 0.0;
    float hit = -1.0;
    float hitEsc = 1.0;
    vec4 hitTrap = vec4(1e6);
    vec3 glow = vec3(0.0);

    for (int i = 0; i < 64; i++){
        vec3 p = eye + rd * dist;
        vec4 trap = vec4(1e6);
        float esc;
        float d = deMandelbulb(p, power, trap, esc);

        // Near misses bleed a little colour into the void, which is what gives
        // the bulb its halo without a second pass. The hue tracks the sample's
        // radius: keyed to the orbit trap instead, this accumulates a nearly
        // constant wash over 64 steps and drowns out the surface shading.
        glow += palette(0.1 * t + 1.5 * length(p) + 0.3) * exp(-d * 22.0) * 0.011;

        if (d < 0.0012 * dist){ hit = dist; hitTrap = trap; hitEsc = esc; break; }
        dist += d * 0.85;                 // DE is conservative; stay under 1.0
        if (dist > 6.0) break;
    }

    vec3 col = glow;

    if (hit > 0.0){
        vec3 p = eye + rd * hit;
        vec3 n = calcNormal(p, power, 0.0012);

        // Orbit traps drive the colour; the surface has no texture of its own.
        // Mixing three trap axes spreads the hue across the whole ramp instead
        // of parking it on one accent.
        // Surface points never escape, so the escape count saturates there and
        // is useless for colour. Radius, orbit trap and facing direction all
        // vary across the lobes, so those carry the hue instead.
        // Hue has to vary *smoothly* over the surface. Driving it hard from the
        // orbit traps varies it per-pixel instead, and shading then averages
        // that back down to mud. So: a slow gradient from radius and facing
        // direction, with only a light trap term for texture.
        float hue = 0.08 * t + 0.30 + 0.7 * length(p) + 0.30 * n.y + 0.18 * hitTrap.x;
        vec3 base = palette(hue);

        // Two coloured key lights a third of the ramp apart, so the lit and
        // shadowed faces land on different neons.
        vec3 l1 = normalize(vec3(0.6, 0.8, -0.4));
        vec3 l2 = normalize(vec3(-0.7, -0.2, 0.5));
        float d1 = max(dot(n, l1), 0.0);
        float d2 = max(dot(n, l2), 0.0);
        float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.5);
        // Cheap ambient occlusion: distant hits sit deeper in the creases.
        float ao = 1.0 / (1.0 + hit * 0.55);

        // Keep the fill and rim hues near the key. Spread them a third of the
        // ramp apart and the three sum to white, which greys out the lobes.
        col += base * (0.14 + 1.05 * d1) * ao;
        col += palette(hue + 0.1) * d2 * 0.55 * ao;
        col += palette(hue + 0.19) * rim * 1.15;
        col += base * 0.12;
    }

    col *= 1.0 - 0.45 * smoothstep(0.6, 1.7, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.85));
    fragColor = vec4(col, 1.0);
}

// Boxfold Cathedral — a raymarched Mandelbox (Mandelbulber "mandelbox") at
// negative scale, which hollows the solid out into vaulted interiors.
#define TAU 6.28318530718

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Tglad's Mandelbox: reflect back inside the box, invert through the shell,
// scale, repeat. dr carries the accumulated scale for the distance estimate.
float deMandelbox(vec3 pos, float scale, inout vec4 trap){
    vec3 z = pos;
    float dr = 1.0;
    for (int i = 0; i < 11; i++){
        z = clamp(z, -1.0, 1.0) * 2.0 - z;          // box fold
        float r2 = dot(z, z);
        if (r2 < 0.25){                              // sphere fold
            float t = 4.0;
            z *= t; dr *= t;
        } else if (r2 < 1.0){
            float t = 1.0 / r2;
            z *= t; dr *= t;
        }
        z = scale * z + pos;
        dr = dr * abs(scale) + 1.0;
        trap = min(trap, vec4(abs(z), dot(z, z)));
    }
    return length(z) / abs(dr);
}

vec3 calcNormal(vec3 p, float scale, float eps){
    vec2 k = vec2(1.0, -1.0);
    vec4 t = vec4(1e6);
    return normalize(
        k.xyy * deMandelbox(p + k.xyy * eps, scale, t) +
        k.yyx * deMandelbox(p + k.yyx * eps, scale, t) +
        k.yxy * deMandelbox(p + k.yxy * eps, scale, t) +
        k.xxx * deMandelbox(p + k.xxx * eps, scale, t));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    // Negative scale is what opens the vaults; drifting it keeps the interior
    // slowly rebuilding itself.
    float scale = -2.05 + 0.09 * sin(t * 0.17);

    // Far enough out that the whole vault reads against black; closer than
    // about 5.5 and the camera sits inside the structure.
    float a = t * 0.11;
    vec3 eye = vec3(cos(a) * 5.9, 1.5 + 0.7 * sin(t * 0.13), sin(a) * 5.9);
    vec3 fwd = normalize(vec3(0.0, 0.0, 0.0) - eye);
    vec3 rgt = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
    vec3 up  = cross(rgt, fwd);
    vec3 rd  = normalize(uv.x * rgt + uv.y * up + 1.75 * fwd);

    float dist = 0.0;
    float hit = -1.0;
    vec4 hitTrap = vec4(1e6);
    vec3 glow = vec3(0.0);

    for (int i = 0; i < 78; i++){
        vec3 p = eye + rd * dist;
        vec4 trap = vec4(1e6);
        float d = deMandelbox(p, scale, trap);
        glow += palette(0.09 * t + 0.55 * length(p) + 0.15) * exp(-d * 26.0) * 0.008;
        if (d < 0.0011 * dist){ hit = dist; hitTrap = trap; break; }
        dist += d * 0.8;               // folding DEs overestimate near creases
        if (dist > 18.0) break;
    }

    vec3 col = glow;

    if (hit > 0.0){
        vec3 p = eye + rd * hit;
        vec3 n = calcNormal(p, scale, 0.0011);

        // Smooth gradient across the structure, lightly textured by the trap.
        // The box's faces are flat, so radius barely varies — but the face
        // normal does, and it is constant per face. Keying off the normal gives
        // each face its own neon; a heavy trap term here just returns to
        // per-pixel noise, which shading averages back to grey.
        float hue = 0.07 * t + 0.15 + 0.3 * length(p)
                  + 0.45 * n.y + 0.3 * n.x + 0.15 * hitTrap.x;
        vec3 base = palette(hue);

        vec3 l1 = normalize(vec3(0.5, 0.9, -0.3));
        vec3 l2 = normalize(vec3(-0.6, -0.3, 0.6));
        float d1 = max(dot(n, l1), 0.0);
        float d2 = max(dot(n, l2), 0.0);
        float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.2);
        float ao = 1.0 / (1.0 + hit * 0.3);

        // Keep the fill and rim hues near the key. Spread them a third of the
        // ramp apart and the three sum to white, which is what greys the faces.
        col += base * (0.14 + 1.25 * d1) * ao;
        col += palette(hue + 0.11) * d2 * 0.6 * ao;
        col += palette(hue + 0.2) * rim * 1.2;
    }

    col *= 1.0 - 0.4 * smoothstep(0.65, 1.7, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.87));
    fragColor = vec4(col, 1.0);
}

// Menger Vault — a raymarched Menger sponge (Mandelbulber "menger_sponge"),
// orbited slowly so its square voids line up and open at every pass.
#define TAU 6.28318530718

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Fold into the sorted positive octant, scale by 3, cut the middle cross.
// Three levels. Each extra level divides the smallest void by three, and past
// this the detail falls under a pixel at preview size and the sponge dissolves
// into aliasing speckle. The loop count and the pow() below must stay in step.
float deMenger(vec3 z, inout vec4 trap){
    float scale = 3.0;
    for (int n = 0; n < 3; n++){
        z = abs(z);
        if (z.x < z.y) z.xy = z.yx;
        if (z.x < z.z) z.xz = z.zx;
        if (z.y < z.z) z.yz = z.zy;
        trap = min(trap, vec4(abs(z), dot(z, z)));
        z = z * scale - vec3(scale - 1.0, scale - 1.0, 0.0);
        if (z.z < -0.5 * (scale - 1.0)) z.z += (scale - 1.0);
    }
    vec3 d = abs(z) - vec3(1.0);
    float box = min(max(d.x, max(d.y, d.z)), 0.0) + length(max(d, 0.0));
    return box * pow(scale, -3.0);
}

vec3 calcNormal(vec3 p, float eps){
    vec2 k = vec2(1.0, -1.0);
    vec4 t = vec4(1e6);
    return normalize(
        k.xyy * deMenger(p + k.xyy * eps, t) +
        k.yyx * deMenger(p + k.yyx * eps, t) +
        k.yxy * deMenger(p + k.yxy * eps, t) +
        k.xxx * deMenger(p + k.xxx * eps, t));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    // Orbit at a slight tilt so the square voids swing open and shut.
    float a = t * 0.13;
    float rad = 2.55 + 0.3 * sin(t * 0.11);
    vec3 eye = vec3(cos(a) * rad, 0.75 * sin(t * 0.157), sin(a) * rad);
    vec3 fwd = normalize(-eye);
    vec3 rgt = normalize(cross(fwd, vec3(0.0, 1.0, 0.0)));
    vec3 up  = cross(rgt, fwd);
    vec3 rd  = normalize(uv.x * rgt + uv.y * up + 1.8 * fwd);

    float dist = 0.0;
    float hit = -1.0;
    vec4 hitTrap = vec4(1e6);
    vec3 glow = vec3(0.0);

    for (int i = 0; i < 72; i++){
        vec3 p = eye + rd * dist;
        vec4 trap = vec4(1e6);
        float d = deMenger(p, trap);
        // Light leaking out of the voids.
        glow += palette(0.09 * t + 0.6 * length(p) + 0.45) * exp(-d * 30.0) * 0.009;
        if (d < 0.0014 * dist){ hit = dist; hitTrap = trap; break; }
        dist += d * 0.9;
        if (dist > 9.0) break;
    }

    vec3 col = glow;

    if (hit > 0.0){
        vec3 p = eye + rd * hit;
        vec3 n = calcNormal(p, 0.0022);

        // Every face of a sponge is axis-aligned, so the normal alone gives
        // three flat colours. Depth into the structure breaks that up.
        float hue = 0.06 * t + 0.48
                  + 0.34 * n.y + 0.26 * n.x
                  + 0.5 * length(p) + 0.16 * hitTrap.x;
        vec3 base = palette(hue);

        vec3 l1 = normalize(vec3(0.55, 0.8, -0.35));
        vec3 l2 = normalize(vec3(-0.5, -0.35, 0.7));
        float d1 = max(dot(n, l1), 0.0);
        float d2 = max(dot(n, l2), 0.0);
        float rim = pow(1.0 - max(dot(n, -rd), 0.0), 2.0);
        float ao = 1.0 / (1.0 + hit * 0.45);

        col += base * (0.13 + 1.2 * d1) * ao;
        col += palette(hue + 0.1) * d2 * 0.55 * ao;
        col += palette(hue + 0.2) * rim * 1.25;
    }

    col *= 1.0 - 0.42 * smoothstep(0.6, 1.7, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.87));
    fragColor = vec4(col, 1.0);
}

// Liquid Metatron — a breathing sacred-geometry lattice smeared into itself by
// accumulated time-offset trails (feedback look, no framebuffer required).
#define TAU 6.28318530718

mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

float segment(vec2 p, vec2 a, vec2 b){
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Distance to the metatron figure, folded into a 6-fold wedge so one wedge of
// primitives draws the whole mandala.
float figure(vec2 p, float t){
    float s = 1.0 + 0.06 * sin(t * 0.7);
    p /= s;
    p *= rot(t * 0.12);

    float a = atan(p.y, p.x);
    float r = length(p);
    a = mod(a + TAU / 12.0, TAU / 6.0) - TAU / 12.0;
    vec2 q = vec2(cos(a), sin(a)) * r;

    float d = 1e4;
    d = min(d, abs(length(q) - 0.16));
    d = min(d, abs(length(q - vec2(0.42, 0.0)) - 0.16));
    d = min(d, abs(length(q - vec2(0.84, 0.0)) - 0.16));
    d = min(d, segment(q, vec2(0.0, 0.0), vec2(0.84, 0.0)));
    d = min(d, segment(q, vec2(0.42, 0.0), vec2(0.21, 0.3637)));
    d = min(d, segment(q, vec2(0.84, 0.0), vec2(0.42, 0.7275)));
    d = min(d, segment(q, vec2(0.42, 0.0), vec2(0.42, 0.7275)));
    return d * s;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    vec3 col = vec3(0.0);
    for (int i = 0; i < 7; i++){
        float fi = float(i);
        float ti = t - fi * 0.055;
        vec2 p = uv * rot(-fi * 0.02) * (1.0 + fi * 0.012);
        float d = figure(p, ti);
        float glow = 0.0011 / (d * d + 0.00025);
        // Hue drifts with radius and a gentle directional tilt. Deliberately no
        // atan() term here: its branch cut would show as a hard seam on -x.
        float hue = 0.09 * ti + fi * 0.04 + length(uv) * 0.85
                  + dot(uv, vec2(0.09, 0.05));
        col += palette(hue) * glow * exp(-fi * 0.55);
    }
    col *= 0.38;

    col += palette(0.2 * t + 0.5) * 0.006 / (dot(uv, uv) + 0.04);
    col *= 1.0 - 0.55 * smoothstep(0.5, 1.5, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.85));
    fragColor = vec4(col, 1.0);
}

// Hexad Bloom — a flower-of-life lattice receding down a twelve-slice
// kaleidoscopic tunnel, thin neon rings dissolving into the dark.
#define TAU 6.28318530718

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Distance to the nearest flower-of-life ring on a hexagonal lattice.
float flower(vec2 p, float r){
    vec2 s = vec2(1.0, 1.7320508);
    vec2 a = mod(p, s) - s * 0.5;
    vec2 b = mod(p + s * 0.5, s) - s * 0.5;
    return abs(min(length(a), length(b)) - r);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;

    float r = length(uv);
    float a = atan(uv.y, uv.x);

    // Twelve-slice kaleidoscopic fold, slowly precessing.
    a = abs(mod(a + t * 0.05, TAU / 6.0) - TAU / 12.0);

    // Tunnel: dz runs as 1/r so the lattice recedes to a vanishing point.
    float dz = 2.7 / (r + 0.16);
    float depth = dz + t * 1.2;

    // Ring thickness is corrected by the tunnel's own derivative so rings stay a
    // constant width on screen instead of aliasing into spokes near the centre.
    float k = (r + 0.16) * (r + 0.16) / 2.7;

    vec3 col = vec3(0.0);
    for (int i = 0; i < 2; i++){
        float fi = float(i);
        vec2 tp = vec2(a * 5.0, depth) * (1.0 + fi * 0.5) + vec2(fi * 0.7, 0.0);
        float ds = flower(tp, 0.36) * k;
        col += palette(0.06 * t - depth * 0.13 + fi * 0.22)
             * (0.00035 / (ds * ds + 0.00012)) * (1.0 - 0.45 * fi);
    }

    // Fog on the spatial part of the depth only, so it does not crawl with time.
    col *= exp(-dz * 0.17);
    col *= smoothstep(0.0, 0.28, r);
    col *= 1.0 - 0.35 * smoothstep(0.7, 1.6, r);
    col = col / (1.0 + col);
    col = pow(col, vec3(0.9));
    fragColor = vec4(col, 1.0);
}

// Moiré Yantra — three counter-rotating ring systems beating against each other
// into moiré fringes, with a pair of yantra triangles orbiting a bindu.
#define TAU 6.28318530718

mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

// LucidSoup neon ramp: magenta -> cyan -> acid green -> magenta.
vec3 palette(float t){
    t = fract(t) * 3.0;
    vec3 m = vec3(1.00, 0.06, 0.94);
    vec3 c = vec3(0.00, 1.00, 1.00);
    vec3 g = vec3(0.22, 1.00, 0.08);
    if (t < 1.0) return mix(m, c, t);
    if (t < 2.0) return mix(c, g, t - 1.0);
    return mix(g, m, t - 2.0);
}

// Distance to an equilateral triangle outline.
float triOutline(vec2 p, float r){
    const float k = 1.7320508;
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return abs(-length(p) * sign(p.y));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    float t = iTime;
    vec3 col = vec3(0.0);

    float m = 1.0;
    for (int i = 0; i < 3; i++){
        float fi = float(i);
        vec2 p = uv * rot(t * 0.07 * (fi + 1.0))
               + vec2(sin(t * 0.23 + fi), cos(t * 0.19 + fi)) * 0.06;
        m *= sin(length(p) * (26.0 + fi * 3.5) - t * 1.2 + fi * 1.7);
    }
    col += palette(0.1 * t + length(uv) * 0.5) * pow(abs(m), 6.0) * 1.4;

    for (int i = 0; i < 2; i++){
        float fi = float(i);
        vec2 p = uv * rot(t * 0.15 * (fi * 2.0 - 1.0) + fi * 3.14159);
        float d = triOutline(p, 0.62 + 0.03 * sin(t * 0.9 + fi * 2.0));
        col += palette(0.14 * t + 0.4 + fi * 0.25) * (0.0022 / (d * d + 0.0006));
    }

    col += vec3(1.0, 0.6, 1.0) * 0.015 / (dot(uv, uv) + 0.02);
    col *= 1.0 - 0.6 * smoothstep(0.6, 1.55, length(uv));
    col = col / (1.0 + col);
    col = pow(col, vec3(0.88));
    fragColor = vec4(col, 1.0);
}
